from collections import defaultdict, Counter

def solve(tickets):
    graph = defaultdict(list)
    for a, b in tickets:
        graph[a].append(b)
    for destinations in graph.values():
        destinations.sort(reverse=True)
    stack, route = ["JFK"], []
    while stack:
        airport = stack[-1]
        if graph[airport]:
            stack.append(graph[airport].pop())
        else:
            route.append(stack.pop())
    route.reverse()
    if len(route) != len(tickets) + 1:
        return []
    counts = Counter((a, b) for a, b in tickets)
    for a, b in zip(route, route[1:]):
        if counts[(a, b)] == 0:
            return []
        counts[(a, b)] -= 1
    return route

def solve(n):
    if n < 0:
        return []
    cols, down, up = set(), set(), set()
    positions, ans = [], []
    def dfs(r):
        if r == n:
            ans.append(["." * c + "Q" + "." * (n - c - 1)
                        for c in positions])
            return
        for c in range(n):
            if c in cols or r - c in down or r + c in up:
                continue
            cols.add(c); down.add(r - c); up.add(r + c)
            positions.append(c)
            dfs(r + 1)
            positions.pop()
            cols.remove(c); down.remove(r - c); up.remove(r + c)
    dfs(0)
    return ans

def solve(board):
    if len(board) != 9 or any(len(row) != 9 for row in board):
        return None
    board = [list(row) for row in board]
    rows, cols, boxes = [set() for _ in range(9)], [set() for _ in range(9)], [set() for _ in range(9)]
    empty = []
    digits = set("123456789")
    for r in range(9):
        for c in range(9):
            x = board[r][c]
            b = (r // 3) * 3 + c // 3
            if x == ".":
                empty.append((r, c))
            elif x not in digits or x in rows[r] or x in cols[c] or x in boxes[b]:
                return None
            else:
                rows[r].add(x); cols[c].add(x); boxes[b].add(x)
    def candidates(r, c):
        return digits - rows[r] - cols[c] - boxes[(r // 3) * 3 + c // 3]
    def dfs(pos):
        if pos == len(empty):
            return True
        best = min(range(pos, len(empty)),
                   key=lambda i: len(candidates(*empty[i])))
        empty[pos], empty[best] = empty[best], empty[pos]
        r, c = empty[pos]
        b = (r // 3) * 3 + c // 3
        for x in sorted(candidates(r, c)):
            board[r][c] = x
            rows[r].add(x); cols[c].add(x); boxes[b].add(x)
            if dfs(pos + 1):
                return True
            rows[r].remove(x); cols[c].remove(x); boxes[b].remove(x)
            board[r][c] = "."
        empty[pos], empty[best] = empty[best], empty[pos]
        return False
    return board if dfs(0) else None

